 * Consent Form Handler
 * Manages form submission and state
 */

class ConsentForm {
    constructor(formId) {
        this.form = document.getElementById(formId);
        this.consentCheckbox = document.getElementById('consentCheckbox');
        this.submitButton = this.form.querySelector('button[type="submit"]');

        this.init();
    }

    init() {
        // Add form submission handler
        this.form.addEventListener('submit', (e) => this.handleSubmit(e));

        // Update submit button state based on checkbox
        this.consentCheckbox.addEventListener('change', () => this.updateSubmitState());

        // Initial state
        this.updateSubmitState();
    }

    updateSubmitState() {
        // Enable/disable submit button based on checkbox state
        const isChecked = this.consentCheckbox.checked;
        this.submitButton.disabled = !isChecked;

        // Update aria-label for better accessibility feedback
        if (isChecked) {
            this.submitButton.removeAttribute('aria-label');
        } else {
            this.submitButton.setAttribute('aria-label', 'Accept & Continue (disabled until you agree to terms)');
        }
    }

    handleSubmit(e) {
        e.preventDefault();

        // Validate form
        if (!this.form.checkValidity()) {
            // Browser will show native validation message
            this.consentCheckbox.focus();
            return;
        }

        // Simulate form submission
        this.showSuccessMessage();
    }

    showSuccessMessage() {
        // Disable form while showing message
        this.form.style.opacity = '0.5';
        this.submitButton.disabled = true;
        this.submitButton.textContent = 'Terms accepted ✓';

        // Show confirmation (in a real app, this would be an API call)
        setTimeout(() => {
            alert('Thank you for accepting our terms of use!');
            // Reset form
            this.form.style.opacity = '1';
            this.form.reset();
            this.updateSubmitState();
            this.consentCheckbox.focus();
        }, 600);
    }
}

/**
 * Handle cancel button click
 */
function handleCancel() {
    if (confirm('Are you sure you want to cancel?')) {
        // In a real app, redirect or close modal
        console.log('User cancelled consent form');
        alert('Consent cancelled. Redirecting...');
    }
}

/**
 * Initialize form when DOM is ready
 */
document.addEventListener('DOMContentLoaded', () => {
    new ConsentForm('consentForm');
});
